WITH transactions_by_account AS (SELECT account_id, ROUND((100 * SUM(CASE WHEN merchant = 'Starbucks' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_starbucks FROM transactions WHERE merchant IS NOT NULL GROUP BY account_id) SELECT a.status, a.balance, tba.pct_starbucks FROM accounts a INNER JOIN transactions_by_account tba ON a.id = tba.account_id ORDER BY a.balance DESC, pct_starbucks DESC
